def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """
    Checks if any two numbers in the given list are closer to each other than the given threshold.

    :param numbers: List of float numbers
    :param threshold: The maximum absolute difference between two numbers
    :return: True if any two numbers in the list are closer to each other than the threshold, False otherwise
    """
    for i in range(len(numbers)):
        for j in range(i + 1, len(numbers)):
            if abs(numbers[i] - numbers[j]) < threshold:
                return True
    return False

def separate_paren_groups(paren_string: str) -> List[str]:
    stack = []
    current_group = ""
    groups = []

    for char in paren_string:
        if char == "(":
            stack.append(char)
            current_group += char
        elif char == ")":
            stack.pop()
            current_group += char
            if not stack:
                groups.append(current_group[1:-1])
                current_group = ""

    if stack:
        raise ValueError("Unbalanced parentheses")
    return groups

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def mean_absolute_deviation(numbers: List[float]) -> float:
    mean = sum(numbers) / len(numbers)
    absolute_deviations = [abs(x - mean) for x in numbers]
    return sum(absolute_deviations) / len(absolute_deviations)

def sum_of_factorials_optimized(n):
