def optimize_seating(M, N, K, L, D, chatting_pairs):
  """
  Optimize the placement of aisles in a classroom to minimize the amount of chatting between students.

  Args:
  M (int): The number of rows in the classroom.
  N (int): The number of columns in the classroom.
  K (int): The number of horizontal aisles to add.
  L (int): The number of vertical aisles to add.
  D (int): The number of chatting pairs in the classroom.
  chatting_pairs (list of tuples): A list of tuples, each containing the positions (Xi, Yi) and (Pi, Qi) of a chatting pair.

  Returns:
  (str, str): Two space-separated strings representing the optimal row and column indices for the aisles.
  """
  # Initialize variables
  row_chatting_pairs = [[0] * N for _ in range(M)]
  col_chatting_pairs = [[0] * M for _ in range(N)]
  horizontal_positions = set()
  vertical_positions = set()

  # Count number of chatting pairs in each cell
  for (Xi, Yi), (Pi, Qi) in chatting_pairs:
    row_chatting_pairs[Xi][Yi] += 1
    col_chatting_pairs[Pi][Qi] += 1

  # Add horizontal aisles
  for i in range(M):
    for j in range(N):
      if row_chatting_pairs[i][j] > 0:
        for k in range(j, N):
          if col_chatting_pairs[i][k] > 0 and (k - j) > 1 and (k - j) not in horizontal_positions:
            horizontal_positions.add(k - j)
            K -= 1
            L -= 1
            if K == 0 or L == 0:
              break

  # Add vertical aisles
  for i in range(N):
    for j in range(M):
      if col_chatting_pairs[j][i] > 0:
        for k in range(j, M):
          if row_chatting_pairs[k][i] > 0 and (k - j) > 1 and (k - j) not in vertical_positions:
            vertical_positions.add(k - j)
            K -= 1
            L -= 1
            if K == 0 or L == 0:
              break

  # Find optimal row and column indices for aisles
  row_aisle_indices = []
  col_aisle_indices = []

  for i in range(M):
    for j in range(N):
      if row_chatting_pairs[i][j] > 0 and str(j) not in horizontal_positions and str(i) not in vertical_positions:
        row_aisle_indices.append(str(j))

  for i in range(N):
    for j in range(M):
      if col_chatting_pairs[j][i] > 0 and str(i) not in horizontal_positions and str(j) not in vertical_positions:
        col_aisle_indices.append(str(j))

  return " ".join(row_aisle_indices), " ".join(col_aisle_indices)

def count_passing_ways(n, m):
    # Initialize a 2D list to store the dynamic programming states
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: No passes
    for i in range(n + 1):
        dp[i][0] = 1

    # Fill the dynamic programming table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            # Calculate the number of passing ways for student i
            dp[i][j] = (dp[i - 1][j - 1] + dp[i - 1][j]) % 1000000007

    return dp[n][m]

def max_energy(beads):
    # Initialize a dictionary to store the best energy values for each merge point
    dp = {}

    # Initialize the first merge point, which is the initial beads
    dp[0] = 0
    for i in range(len(beads)):
        dp[i] = dp[i - 1] + beads[i] * beads[i - 1] * beads[i + 1]

    # Loop through each possible merge point and update the best energy values
    for i in range(1, len(beads)):
        for j in range(i + 1, len(beads)):
            dp[j] = max(dp[j], dp[j - 1] + beads[j] * beads[j - 1] * beads[j + 1])

    # Return the maximum energy
    return dp[len(beads) - 1]

def largest_prime_factor(n: int) -> int:
    largest_factor = 1
    for potential_factor in range(2, int(n ** 0.5) + 1):
        if n % potential_factor == 0:
            largest_factor = potential_factor
            n //= potential_factor
            if n == 1:
                break
    else:
        largest_factor = n
    return largest_factor

def count_coprime_pairs(x0, y0):
    count = 0
    for a in range(1, y0 // x0 + 1):
        b = y0 // x0 // a
        if a * b == y0 / x0 and gcd(a, b) == 1:
            if a == b:
                count += 1
            else:
                count += 2
    return count

def gcd(a, b):
    if b == 0:
        return a
    else:
        return gcd(b, a % b)

