def min_remaining_space(V, n, volumes):
    # Create a two-dimensional table to store the results of the recurrence
    dp = [[0] * (n+1) for _ in range(V+1)]

    # Initialize the first row and column with the values from the given problem statement
    for i in range(1, n+1):
        dp[volumes[i-1]][i] = 1
    for j in range(1, V+1):
        dp[j][1] = V - j

    # Fill in the remaining cells of the table using the recurrence relation
    for i in range(2, n+1):
        for j in range(2, V+1):
            dp[j][i] = min(dp[j-volumes[i-1]][i-1] + volumes[i-1], dp[j][i-1])

    # Return the minimum remaining space
    return V - dp[V][n]

def jinjin_savings_plan(budgets: List[int]) -> int:
    total_amount = 0
    for i, budget in enumerate(budgets):
        if budget - 100 < 0:
            return -i
        else:
            total_amount += (budget - 100) * 1.2
    return total_amount

def hanoi_double_iterative(n: int):
    if n == 1:
        return 2
    if n == 2:
        return 6
    if n == 3:
        return 14
    num_moves = 0
    while n > 0:
        num_moves += 2 * n
        n -= 1
    return num_moves
